import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a cyclic board labeled 1 through {m}, define the relation x ≻_{t} y to mean the clockwise modular distance from y to x (taken modulo {m}) lies in {1,2,...,t}. Given an integer {k} and a threshold vector [t_list] = (t_1, t_2, ..., t_{k}), count the number of k-tuples (x_1, x_2, ..., x_{k}) with each x_i in {1,2,...,{m}} such that for every i = 1, 2, ..., {k}-1, x_i ≻_{t_list[i-1]} x_{i+1}, and also x_{k} ≻_{t_list[{k}-1]} x_{1}. Return the exact integer count.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate parameters for a harder cyclic dominance counting problem.
# We ensure sum(t_i) >= 2*m so that multiple wrap counts are possible,
# making the counting non-trivial and strictly harder than the seed.
while True:
    m = rng.randint(13, 50)
    k = rng.randint(4, 8)
    lo = max(2, m // 3)
    hi = m - 2
    t_list = [rng.randint(lo, hi) for _ in range(k)]
    # Avoid the degenerate case where all thresholds are equal.
    if len(set(t_list)) == 1:
        idx = rng.randrange(k)
        if t_list[idx] < hi:
            t_list[idx] += 1
        else:
            t_list[idx] -= 1
    sum_t = sum(t_list)
    if sum_t < 2 * m:
        continue  # enforce at least two possible multiples of m
    # Quick feasibility check: compute dp_k[0] to ensure there is at least one valid sequence.
    dp = [0] * m
    dp[0] = 1
    for ti in t_list:
        new = [0] * m
        for r in range(m):
            val = dp[r]
            if val:
                for s in range(1, ti + 1):
                    new[(r + s) % m] += val
        dp = new
    if dp[0] == 0:
        continue  # try again if no solutions
    return {'m': m, 'k': k, 't_list': t_list}

    def verifier(assign):
# Validate and compute the exact count.
# The count equals m * dp_k[0], where dp_k[0] is the number of sequences (d_1,...,d_k) with
# 1 <= d_i <= t_i and sum(d_i) ≡ 0 (mod m).
# Difficulty checks: ensure m >= 13, k >= 4, sum(t_i) >= 2m, thresholds in [1, m-1],
# and at least two distinct threshold values.
try:
    m = assign['m']
    k = assign['k']
    t_list = assign['t_list']
except Exception:
    # Missing keys
    return (False, None)
# Basic type and domain checks
if not (isinstance(m, int) and isinstance(k, int) and isinstance(t_list, list)):
    return (False, None)
if m < 13 or k < 4:
    # too small, not sufficiently hard
    return (False, None)
if len(t_list) != k:
    return (False, None)
if any((not isinstance(t, int)) for t in t_list):
    return (False, None)
if any(t < 1 or t >= m for t in t_list):
    return (False, None)
if sum(t_list) < 2 * m:
    # enforce multiple wraps for difficulty
    return (False, None)
if len(set(t_list)) < 2:
    # avoid overly symmetric trivial instances
    return (False, None)
# Compute dp: number of length-i sequences with sum ≡ r (mod m)
dp = [0] * m
dp[0] = 1
for ti in t_list:
    new = [0] * m
    # Transition by adding any s in {1,...,ti}
    for r in range(m):
        val = dp[r]
        if val:
            for s in range(1, ti + 1):
                new[(r + s) % m] += val
    dp = new
ways = dp[0]
if ways <= 0:
    # No valid sequences; instance invalid (should be rare due to generator checks)
    return (False, None)
answer = m * ways
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

